#! /usr/bin/perl
use Getopt::Long;
use POSIX qw(ceil floor);
#######################################################
# Author:  Andreas Olofsson, Nov 11, 2015
#######################################################
$Usage =<<EOF;
#######################################################
Usage: egen.pl  -mode <random|memcpy>
                -n    <number-of-bytes>
                -bl   <max-burst-in-bytes>
#######################################################
Description: 
* Generates random Epiphany 104 bit packet transaction
* Data is completely random
* Data sizes are completely random
* Address fields are random (but legal)
* Random burst sizes up to <max-burst-length>
* Default return address base is 810D0000
* Default destination address base is 83000000
#################################################################
Example1: Generate a random test

egen.pl -mode random -n 1024 -bl 128

Example2:

egen.pl -mode memcpy -n 1024 -dstaddr 90000000 -srcaddr 80000000

################################################################
EOF
$result = GetOptions('mode:s',
		     'dstaddr:s', 
		     'srcaddr:s',
		     'd:s',
		     'c:s',  #ctrlmode 
		     'n:s',
		     'bl:s',
		     '32:s',
    );


if ((!defined $opt_n) | (!defined $opt_mode) ) {
    printf $Usage;
    exit;
}
$n=$opt_n;
$mode=$opt_mode;
#####################################################################
# OPTIONAL OPTIONS
#####################################################################

#MAX BURST
if(defined $opt_bl){
    $burst_max = $opt_bl;
}
else{
    $burst_max = 4;
}

#LIMIT TO 32 BITS
if(defined $opt_32){
    $ctrl_max = 5;
}
else{
    $ctrl_max = 7;
}
if(defined $did){
    $addrid = $opt_did;
}
else{
    $addrid  =hex("0x83000000"); #NOTE: should not be equal to RX ID
}
if(defined $sid){
    $returnid=$sid;
}
else{
    $returnid=hex("0x810D0000");
}
if(defined $opt_c){
    $cltrmode=$opt_c;
}
else{
    $ctrlmode = 5;	
}

$count =0;
$bytes=0;
#Writes
$dstaddr    = hex($opt_dstaddr);
$returnaddr = $returnid+ (hex($opt_srcaddr) & 0x000FFFFF);
while($bytes<$n){
    if($mode eq "random"){
	$ctrlmode = (int(rand(hex($ctrl_max))) + 1)  | 0x1;  #only writes
	$burst    = (int(rand($opt_bl)) + 1);         #variable bursts
    }
    else{

	$burst = $n;
    }
    #BYTES
    if($ctrlmode<2){
	$addrmask = hex("0x0000ffff");
	$maskhi   = hex("0x00000000");
	$masklo   = hex("0x000000FF");
	$incr     = 1;
    }
    #HALF-WORD
    elsif($ctrlmode<4){
	$addrmask = hex("0x0000fffe");
	$maskhi   = hex("0x00000000");
	$masklo   = hex("0x0000FFFF");
	$incr     = 2;
    }
    #WORD
    elsif($ctrlmode<6){
	$addrmask = hex("0x0000fffc");
	$maskhi   = hex("0x00000000");
	$masklo   = hex("0xFFFFFFFF");
	$incr     = 4;
    }
    #DOUBLE
    else{
	$addrmask = hex("0x0000fff8");
	$maskhi   = hex("0xFFFFFFFF");
	$masklo   = hex("0xFFFFFFFF");
	$incr     = 8;
    }
    $burst=floor($burst/$incr);

    #randomize destination address
    if($mode eq "random"){
	$dstaddr    = $addrid + ((int(rand(hex("0xFFFFFFFF"))) + 0) & $addrmask); #filter "D/F group" and illegal alings
	$returnaddr = $returnid+((int(rand(hex("0xFFFFFFFF")))) & $addrmask);
    }
    #create a burst of transactions
    for ($j=0;$j<$burst;$j++){ 
	$datalo     = (int(rand(hex("0xFFFFFFFF"))) + 0) & 0xFFFFFFFF;	
	$datahi     = (int(rand(hex("0xFFFFFFFF"))) + 0) & 0xFFFFFFFF;		    

	#make sure address wasn't used already
	$inuse=0;
	for($k=0;$k<$incr;$k++){	    
	    $addr=$dstaddr+$k;
	    #check if in use
	    if(exists ($usedaddr{$addr})){
		$inuse=1;
	    }
	    #set as used	       
	    $usedaddr{$addr}=1;
	}	   
	if($inuse == 0){
	    $transaction[$count]{dstaddr}   =$dstaddr;
	    $transaction[$count]{srcaddr}   =$datahi;
	    $transaction[$count]{data}      =$datalo;
	    $transaction[$count]{reslo}     =$datalo & $masklo;
	    $transaction[$count]{reshi}     =$datahi & $maskhi; 
	    $transaction[$count]{ctrlmode}  =$ctrlmode;
	    $transaction[$count]{returnaddr}=$returnaddr;
	    $transaction[$count]{burst}     =$burst;		
	    printf("%08x_%08x_%08x_%02x_0000//WRITE (i=%d, j=%d, bytes=%d)\n",
		   $datahi,$datalo,$dstaddr,$ctrlmode, $count, $j, $bytes);
	    $bytes      = $bytes+$incr;
	    $count      = $count+1;
	    $dstaddr    = $dstaddr+$incr;
	    $returnaddr = $returnaddr+$incr;
	}	    	   	   
	else{
	    #printf("ADDR %08x in USE (CTRLMODE=%04x)\n",$dstaddr,$ctrlmode);
	}
	#print "b=$bytes incr=$incr transaction-burst=$burst ctrl=$ctrlmode count=$count use=$inuse n=$n\n";
    }
}
#Reads/Expected results
for ($i=0;$i<($#transaction+1);$i++){
    #Pushing read transactions
    printf("%08x_%08x_%08x_%02x_0000//READ\n",
	   $transaction[$i]{returnaddr},       #address to return to
	   hex("0xDEADBEEF"), 
	   $transaction[$i]{dstaddr},           
	   $transaction[$i]{ctrlmode}&hex(0x6) #turn write into read
	);	
    #Expected results
    printf("%08x_%08x_%08x_%02x\n",
	   $transaction[$i]{reshi},
	   $transaction[$i]{reslo},
	   $transaction[$i]{returnaddr},
	   $transaction[$i]{ctrlmode}
	);	
}

// A stimulus file provides inputs signals to the design under test (DUT).
// This stimulus module is designed to be compatible with verilog simulators,
// emulators, and FPGA prototyping. This is akin to a simple test vector generator
//
// Test Process:
// 1. Zero out memory (or write program)
// 2. Set go signal
// 3. Drive out all valid packets sequentially

module stimulus
  #(parameter DW        = 64,      // Stimulus packet width
    parameter DEPTH     = 1024,    // Memory depth
    parameter CW        = 0,       // bit[0]=valid, [CW-1:1]=timestamp
    parameter MW        = DW + CW, // Memory width (derived)
    parameter FILENAME  = "NONE"   // Simulus hexfile for $readmemh
    )
   (
    // External stimulus load port
    input 	    nreset, // async reset
    input 	    ext_start, // Start driving stimulus
    input 	    ext_clk,// External clock for write path
    input 	    ext_access, // Valid packet for memory
    input [MW-1:0]  ext_packet, // Packet for memory
    // DUT drive port
    input 	    dut_clk, // DUT side clock
    input 	    dut_ready, // DUT ready signal
    output 	    stim_valid, // Packet valid
    output [DW-1:0] stim_packet, // Packet data
    output 	    stim_done // Signals that stimulus is done
    );

   // memory parameters
   parameter MAW = $clog2(DEPTH); // Memory address width

   // state machine parameters
   localparam STIM_IDLE    = 2'b00;
   localparam STIM_ACTIVE  = 2'b01;
   localparam STIM_PAUSE   = 2'b10;
   localparam STIM_DONE    = 2'b11;

   // Local values
   reg [MW-1:0]       ram[0:DEPTH-1];
   reg [1:0] 	      rd_state;
   reg [MAW-1:0]      wr_addr;
   reg [MAW-1:0]      rd_addr;
   reg [1:0] 	      sync_pipe;
   reg 		      mem_read;
   reg [MW-1:0]       mem_data;
   reg [CW:0] 	      rd_delay;
   wire 	      dut_start;
   wire 	      valid_packet;

   //#################################
   // Init memory if configured
   //#################################
   generate
      if(!(FILENAME=="NONE"))
	initial
	  begin
	     $display("Driving stimulus from %s", FILENAME);
	     $readmemh(FILENAME, ram);
	  end
   endgenerate

   //#################################
   // Write port state machine
   //#################################

   always @ (posedge ext_clk or negedge nreset)
     if(!nreset)
       wr_addr[MAW-1:0] <= 'b0;
     else if(ext_access)
       wr_addr[MAW-1:0] <= wr_addr[MAW-1:0] + 1;

   //Synchronize ext_start to dut_clk domain
   always @ (posedge dut_clk or negedge nreset)
     if(!nreset)
       sync_pipe[1:0] <= 'b0;
     else
       sync_pipe[1:0] <= {sync_pipe[0],ext_start};

   assign dut_start = sync_pipe[1];

   //#################################
   // Read port state machine
   //#################################
   //1. Start on dut_start
   //2. Drive stimulus while dut is ready
   //3. Set end state on special end packet (bit 0)

   always @ (posedge dut_clk or negedge nreset)
     if(!nreset)
       begin
	  rd_state[1:0]      <= STIM_IDLE;
	  rd_addr[MAW-1:0]   <= 'b0;
	  rd_delay           <= 'b0;
       end
     else if(dut_ready)
       case (rd_state[1:0])
	 STIM_IDLE :
	   rd_state[1:0] <= dut_start ? STIM_ACTIVE : STIM_IDLE;
	 STIM_ACTIVE :
	   begin
	      rd_state[1:0] <= (|rd_delay) ? STIM_PAUSE :
			       ~stim_valid ? STIM_DONE  :
	                                     STIM_ACTIVE;
	      rd_addr[MAW-1:0] <= rd_addr[MAW-1:0] + 1'b1;
	      rd_delay         <= (CW > 1) ? mem_data[CW:1] : 'b0;
	   end
	 STIM_PAUSE :
	   begin
	      rd_state[1:0] <= (|rd_delay) ? STIM_PAUSE : STIM_ACTIVE;
	      rd_delay      <= rd_delay - 1'b1;
	   end
       endcase // case (rd_state[1:0])

   //Output Driver
   assign stim_done    = (rd_state[1:0] == STIM_DONE);
   assign valid_packet = (CW==0) | mem_data[0];

   //#################################
   // RAM
   //#################################

   //write port
   always @(posedge ext_clk)
     if(ext_access)
       ram[wr_addr[MAW-1:0]] <= ext_packet[MW-1:0];

   //read port
   always @ (posedge dut_clk)
     begin
	mem_data[MW-1:0] <= ram[rd_addr[MAW-1:0]];
	mem_read         <= (rd_state==STIM_ACTIVE); //mem-cycle adjust
     end

   //Shut off access immediately, but pipeline delay by one cycle
   assign stim_valid          = valid_packet & mem_read & ~stim_done;
   assign stim_packet[DW-1:0] = mem_data[MW-1:CW];

endmodule // stimulus

