	       .TARGET(TARGET),
	       .FILENAME(FILENAME))
   testbench(/*AUTOINST*/
	     // Outputs
	     .dut_clk			(dut_clk),
	     .dut_valid			(dut_valid),
	     .dut_packet		(dut_packet[PW-1:0]),
	     .dut_ready			(dut_ready),
	     .dut_status		(dut_status[N-1:0]),
	     .dut_error			(dut_error),
	     .dut_done			(dut_done),
	     .dut_fail			(dut_fail),
	     // Inputs
	     .nreset			(nreset),
	     .clk			(clk),
	     .fastclk			(fastclk),
	     .slowclk			(slowclk),
	     .mode			(mode[2:0]),
	     .ctrl			(ctrl[N-1:0]),
	     .seed			(seed[N-1:0]),
	     .ext_clk			(1'b0),			 // Templated
	     .ext_valid			(1'b0),			 // Templated
	     .ext_packet		({(PW){1'b0}}),		 // Templated
	     .ext_ready			(1'b0));			 // Templated


   //#################################
   // Simulation control
   //#################################

   oh_simctrl #(.TIMEOUT(TIMEOUT),
		.PERIOD_CLK(PERIOD_CLK),
		.PERIOD_SLOWCLK(PERIOD_SLOWCLK),
		.PERIOD_FASTCLK(PERIOD_FASTCLK),
		.RANDOM_DATA(RANDOM_DATA),
		.RANDOM_CLK(RANDOM_CLK))
   oh_simctrl(/*AUTOINST*/
	      // Outputs
	      .nreset			(nreset),
	      .clk			(clk),
	      .fastclk			(fastclk),
	      .slowclk			(slowclk),
	      .mode			(mode[2:0]),
	      // Inputs
	      .dut_fail			(dut_fail),
	      .dut_done			(dut_done));

   //#################################
   // Wavedump
   //#################################

   initial
     begin
	$timeformat(-9, 0, " ns", 20);
	$dumpfile("waveform.vcd");
	$dumpvars(0, testbench);
     end


