   wire			vdd;			// From oh_simctrl of oh_simctrl.v
   wire			vss;			// From oh_simctrl of oh_simctrl.v
   // End of automatics

   oh_stimulus #(.DW(DW),
		 .CW(CW),
		 .FILENAME(FILENAME))
   oh_stimulus(.dut_ready		(1'b1),
