	       .ext_valid		(1'b0),
	       .ext_packet		({(DW + CW){1'b0}}),
	       .ext_clk			(ext_clk),
	       .ext_start		(start),
	       /*AUTOINST*/
	       // Outputs
	       .stim_valid		(stim_valid),
	       .stim_packet		(stim_packet[DW-1:0]),
	       .stim_done		(stim_done),
	       // Inputs
	       .nreset			(nreset));

   oh_simctrl oh_simctrl(.stim_done	(1'b0),
			 .test_done	(1'b1),
			 .test_diff	(1'b0),
			 .dut_active    (1'b1),
			 .clk1		(ext_clk),
			 .clk2		(dut_clk),
			 /*AUTOINST*/
			 // Outputs
			 .nreset		(nreset),
